def transform(grid):
 from collections import Counter
 colors=set(x for row in grid for x in row if x)
 def bbox_area(color):
  pts=[(r,c) for r,row in enumerate(grid) for c,x in enumerate(row) if x==color]
  return (max(r for r,c in pts)-min(r for r,c in pts)+1)*(max(c for r,c in pts)-min(c for r,c in pts)+1)
 frame=max(colors,key=bbox_area)
 pts=[(r,col) for r,row in enumerate(grid) for col,x in enumerate(row) if x==frame]
 a,b=min(r for r,c in pts),max(r for r,c in pts)
 l,rr=min(c for r,c in pts),max(c for r,c in pts)
 out=[row[l:rr+1] for row in grid[a:b+1]]
 n=len(out)
 for r in range(n):
  for col in range(len(out[0])):
   if out[r][col] not in (0,frame):
    v=grid[a+n-1-r][l+col]
    out[r][col]=v if v not in (0,frame) else 0
 return out
